  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C146","C128","C119","C110","C112","C107","C131","C144","C129",
    "C141","C135","C151","C130","C108","C136","C132",
    "C85","C92","C69","C81","C87","C98","C94"
  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C146","C128","C119","C110","C112","C107","C131","C144","C129",
    "C141","C135","C151","C130","C108","C136","C132",
    "C85","C92","C69","C81","C87","C98","C94"
  ],
  "claims": [
    {
      "claim": "L4 human permeability data for the corticosteroid scaffold show high intestinal permeability: prednisolone human Peff 4.4×10^-4 cm/s, fraction absorbed 95%, and Caco-2/MDR-MDCK Papp values of about 18–36×10^-6 cm/s.",
      "card_ids": ["C146","C128","C119","C110","C112","C107","C131","C144","C129"]
    },
    {
      "claim": "Related corticosteroids also show high absorption: hydrocortisone has high in vivo/in vitro intestinal permeability, and prednisone is classified as low-solubility/high-permeability with >99% jejunal absorption.",
      "card_ids": ["C141","C135","C151","C130","C132"]
    },
    {
      "claim": "Prednisolone absorption is essentially complete in clinical settings, supporting efficient absorption of the corticosteroid core.",
      "card_ids": ["C108","C136"]
    },
    {
      "claim": "Solubility records show low but pH-independent aqueous solubility for prednisolone (about 0.22–0.25 mg/mL in water and ~0.5 mg/mL in GI fluids); this is a limitation but not affirmative evidence of F<20% given high permeability and the absence of dose/solubility data for the query.",
      "card_ids": ["C149","C111","C127","C147","C123","C133"]
    },
    {
      "claim": "L3 oral exposure records for prednisolone, prednisone, dexamethasone, methylprednisolone, and hydrocortisone show substantial systemic exposure after oral dosing, consistent with high oral bioavailability for the corticosteroid class.",
      "card_ids": ["C85","C92","C69","C81","C87","C98","C94"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": [
        "C146","C128","C119","C110","C112","C107","C131","C144","C129",
        "C141","C135","C151","C130","C108","C136","C132"
      ]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C149","C111","C127","C147","C123","C133","C137","C113"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C139","C138","C118","C148","C143","C140","C105","C104","C114","C116","C115","C124","C106"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C150","C125","C121","C122","C153","C145","C126","C142"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or pharmacokinetic measurement for the query 16,17-cyclohexylmethylene acetal corticosteroid is present in the supplied records; all evidence is transferred from other corticosteroids.",
    "No direct permeability, solubility, or dissolution measurement for the query molecule itself; the acetal and cyclohexyl substituent may alter these properties relative to prednisolone/hydrocortisone.",
    "First-pass metabolism and gut-wall efflux have not yet been assessed at L4; these are critical determinants of absolute oral bioavailability and will be addressed at L5.",
    "The prandial state and oral dose for the query are unspecified; solubility-limited absorption depends on the dose-to-solubility ratio.",
    "Potential acid-catalyzed hydrolysis of the dioxolane acetal in gastric fluid is unquantified in the supplied records."
  ],
  "decision_summary": "L4 intestinal absorption/permeability evidence for structurally related corticosteroids shows high permeability and near-complete absorption, supporting the absorption component of oral bioavailability. Low aqueous solubility is a limitation but not affirmative evidence of F<20% given high permeability and the absence of dose/solubility data. The high prediction is retained and strengthened with moderate confidence, pending L5 first-pass/efflux assessment."
}

